\set ON_ERROR_STOP on
begin;
insert into auth.users(id) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,5)n;
create function pg_temp.assert_true(ok boolean,description text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',description;end if;end$$;
create function pg_temp.expect_failure(command text,description text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute command;exception when others then failed:=true;end;if not failed then raise exception 'FAILED unexpected success: %',description;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields,event_start_at,registration_closes_at,ends_at)values('70000000-0000-4000-8000-000000000001',auth.uid(),'Scheduled contest','[{"id":"20000000-0000-4000-8000-000000000001","type":"text","label":"Report","description":"","required":false}]',clock_timestamp()+interval '2 days',clock_timestamp()+interval '1 day',clock_timestamp()+interval '3 days');
insert into event_hosts(contest_id,user_id,role)values('70000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','manager');
select pg_temp.expect_failure($q$update contests set starts_at='infinity' where id='70000000-0000-4000-8000-000000000001'$q$,'infinite submission start');
select pg_temp.expect_failure($q$update contests set registration_opens_at='-infinity' where id='70000000-0000-4000-8000-000000000001'$q$,'infinite registration start');
select pg_temp.expect_failure($q$update contests set starts_at=ends_at where id='70000000-0000-4000-8000-000000000001'$q$,'submission equal deadline');
select pg_temp.expect_failure($q$update contests set registration_opens_at=registration_closes_at where id='70000000-0000-4000-8000-000000000001'$q$,'registration equal close');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select register_contest_entry('70000000-0000-4000-8000-000000000001','Original','{}');
insert into contest_submissions(contest_id,user_id,participant_name,answers)values('70000000-0000-4000-8000-000000000001',auth.uid(),'Original','{}');
select pg_temp.assert_true((select registration_opens_at is null and starts_at is null from contests where id='70000000-0000-4000-8000-000000000001'),'legacy null allows existing registration and submission');
update contests set starts_at=clock_timestamp()+interval '4 hours' where id='70000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select starts_at is null from contests where id='70000000-0000-4000-8000-000000000001'),'participant cannot schedule contest');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update contests set approval_required=true,registration_opens_at=clock_timestamp()-interval '1 hour' where id='70000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select register_contest_entry('70000000-0000-4000-8000-000000000001','Pending','{}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
update contests set registration_opens_at=clock_timestamp()+interval '1 hour',starts_at=clock_timestamp()+interval '1 hour' where id='70000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
update event_registrations set attendee_name='Pending edited' where contest_id='70000000-0000-4000-8000-000000000001' and user_id=auth.uid();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
update event_registrations set status='confirmed' where contest_id='70000000-0000-4000-8000-000000000001' and user_id='00000000-0000-4000-8000-000000000003';
select pg_temp.assert_true((select status='confirmed' from event_registrations where user_id='00000000-0000-4000-8000-000000000003'),'future opening does not block manager approval');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
update event_registrations set attendee_name='Edited' where user_id=auth.uid();
select pg_temp.expect_failure($q$update contest_submissions set participant_name='Too early' where contest_id='70000000-0000-4000-8000-000000000001'$q$,'existing submission edit before start');
update event_registrations set status='cancelled' where user_id=auth.uid();
select pg_temp.expect_failure($q$select register_contest_entry('70000000-0000-4000-8000-000000000001','Rejoin','{}')$q$,'RPC rejoin before opening');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.expect_failure($q$insert into event_registrations(contest_id,user_id,attendee_name,answers)values('70000000-0000-4000-8000-000000000001',auth.uid(),'Early','{}')$q$,'raw REST entry before opening');
select pg_temp.expect_failure($q$select register_contest_entry('70000000-0000-4000-8000-000000000001','Early RPC','{}')$q$,'RPC new entry before opening');
select pg_temp.expect_failure($q$insert into contest_submissions(contest_id,user_id,participant_name,answers)values('70000000-0000-4000-8000-000000000001',auth.uid(),'Early','{}')$q$,'raw REST submission before start');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update contests set registration_opens_at=clock_timestamp()-interval '1 minute',starts_at=clock_timestamp()-interval '1 minute' where id='70000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select register_contest_entry('70000000-0000-4000-8000-000000000001','Now open','{}');
insert into contest_submissions(contest_id,user_id,participant_name,answers)values('70000000-0000-4000-8000-000000000001',auth.uid(),'Now open','{}');
select pg_temp.assert_true((select count(*)=1 from contest_submissions where user_id=auth.uid()),'submission opens by server clock');

-- Existing team submissions survive nested FK archival even after a future start is set.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields,participation_mode,team_min_size,team_max_size,registration_closes_at,event_start_at,ends_at) values('70000000-0000-4000-8000-000000000002',auth.uid(),'Team preservation','[{"id":"20000000-0000-4000-8000-000000000001","type":"text","label":"Report","description":"","required":false}]','team',2,2,clock_timestamp()+interval '1 day',clock_timestamp()+interval '2 days',clock_timestamp()+interval '3 days');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select register_contest_entry('70000000-0000-4000-8000-000000000002','Captain','{}','team_create','Preserved');
select set_config('test.team',(select id::text from contest_teams where contest_id='70000000-0000-4000-8000-000000000002'),true);
select set_config('test.code',(select join_code::text from contest_teams where contest_id='70000000-0000-4000-8000-000000000002'),true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select register_contest_entry('70000000-0000-4000-8000-000000000002','Member','{}','team_join',null,current_setting('test.code')::uuid);
insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('70000000-0000-4000-8000-000000000002',auth.uid(),current_setting('test.team')::uuid,'Team paper','{}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update contests set starts_at=clock_timestamp()+interval '1 hour' where id='70000000-0000-4000-8000-000000000002';
reset role;
delete from contest_teams where id=current_setting('test.team')::uuid;
select pg_temp.assert_true((select count(*)=1 and bool_and(team_id is null and participant_name='Team paper') from contest_submissions where contest_id='70000000-0000-4000-8000-000000000002'),'nested team archive preserves submitted content before start');
rollback;
